create extension if not exists pgcrypto;
do $$ begin create role anon nologin; exception when duplicate_object then null; end $$; do $$ begin create role authenticated nologin; exception when duplicate_object then null; end $$;
create schema auth;
create table auth.users (id uuid primary key default gen_random_uuid(), email text, raw_user_meta_data jsonb default '{}'::jsonb, email_confirmed_at timestamptz, encrypted_password text, created_at timestamptz default now());
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('app.uid', true), '')::uuid $$;
create schema net;
create function net.http_post(url text, body jsonb default '{}'::jsonb, headers jsonb default '{}'::jsonb, timeout_milliseconds integer default 1000) returns bigint language sql as $$ select 1::bigint $$;
create table public.profiles (id uuid primary key, user_id text, yor_id text unique, email text, role text not null default 'user' check (role in ('user','admin')), first_name text not null default '', last_name text not null default '', phone text, country text default 'OM', photo text, kyc jsonb, status text not null default 'ACTIVE' check (status in ('ACTIVE','SUSPENDED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), welcome_email_sent_at timestamptz, constraint profiles_yor_id_check check (yor_id ~ '^YOR-[A-Z0-9]{6}$'));
create table public.accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null, type text, name text, currency text not null check (currency = any (array['OMR','XOF','USD','AED','SAR'])), balance numeric not null default 0 check (balance >= 0), available_balance numeric not null default 0 check (available_balance >= 0), reserved_balance numeric not null default 0 check (reserved_balance >= 0), status text default 'ACTIVE', country text, created_at timestamptz default now(), updated_at timestamptz default now(), unique (user_id, currency));
create table public.transactions (id uuid primary key default gen_random_uuid(), reference text not null, kind text not null, sender_id uuid, receiver_id uuid, sender_yor_id text, receiver_yor_id text, asset text not null, network text, amount numeric not null check (amount > 0), fee numeric not null default 0, total numeric not null, status text not null default 'CONFIRMED', note text, created_at timestamptz not null default now(), meta jsonb not null default '{}'::jsonb);
alter table public.transactions add constraint transactions_kind_check check (kind = any (array['FIAT_TRANSFER','CRYPTO_TRANSFER','ADMIN_DEPOSIT','FIAT_EXTERNAL','CRYPTO_BUY','CRYPTO_SELL','CRYPTO_SWAP','CRYPTO_SEND','CRYPTO_TO_BANK']));
create table public.ledger_entries (id bigserial primary key, transaction_id uuid, user_id uuid, asset text, delta numeric, balance_after numeric, created_at timestamptz default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null, type text not null, title text not null, message text not null, transaction_id uuid, data jsonb not null default '{}'::jsonb, read boolean not null default false, created_at timestamptz not null default now());
create table public.email_logs (id uuid primary key default gen_random_uuid(), user_id uuid, transaction_id uuid, email_type text not null, recipient_email text not null, recipient_language text, status text not null default 'PENDING', idempotency_key text not null unique, attempts int not null default 0, brevo_message_id text, error_message text, next_attempt_at timestamptz not null default now(), locked_at timestamptz, created_at timestamptz not null default now(), sent_at timestamptz, delivered_at timestamptz, payload jsonb not null default '{}'::jsonb);
create table public.audit_log (id bigserial primary key, actor_id uuid, action text not null, target_id uuid, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.app_private (key text primary key, value text);
create table public.idempotency_keys (user_id uuid, key text, result jsonb, created_at timestamptz default now(), primary key (user_id, key));
create table public.fx_rates (currency text primary key, per_omr numeric not null);
insert into public.fx_rates values ('OMR',1),('USD',2.6008),('XOF',1492),('AED',9.5466);
create table public.bank_jobs (tx_id uuid primary key, user_id uuid, flow text, scenario text, stages jsonb, idx int not null default 0, started_at timestamptz not null default now(), next_at timestamptz, done boolean not null default false);
create table public.tx_events (id bigserial primary key, transaction_id uuid, user_id uuid, status text, label text, created_at timestamptz default now());
create table public.yor_mail (id uuid primary key default gen_random_uuid(), user_id uuid, category text, transaction_id uuid, subject jsonb, body jsonb, read boolean default false, created_at timestamptz default now());
create table public.recipient_notices (id uuid primary key default gen_random_uuid(), transaction_id uuid, channel text, audience text, user_id uuid, to_phone text, to_email text, country text, language text, status text not null default 'PENDING', attempts int default 0, provider_message_id text, error_message text, next_attempt_at timestamptz default now(), locked_at timestamptz, created_at timestamptz default now(), sent_at timestamptz, idempotency_key text unique, delivery_status text, delivery_checked_at timestamptz, delivered_at timestamptz, delivery_error text);
create table public.user_docs (user_id uuid, doc_name text, data jsonb, updated_at timestamptz default now(), primary key (user_id, doc_name));
create table public.crypto_wallets (id uuid primary key default gen_random_uuid(), user_id uuid, asset text, network text, address text, balance numeric default 0, available_balance numeric default 0, locked_balance numeric default 0);
create table public.notice_dispatch_cfg (id boolean primary key default true, token text, anon_key text, fn_url text, limit_recipient_24h int, limit_sender_24h int, limit_confirm_24h int, sms_countries text[], push_fn_url text);
insert into public.notice_dispatch_cfg (token, anon_key, fn_url, push_fn_url) values (null, null, null, null);
create table public.push_subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid);
create table public.pin_grants (token uuid primary key default gen_random_uuid(), user_id uuid, expires_at timestamptz default now() + interval '5 min');
